    "question": "小湘參加臺北動漫展的密室逃脫解謎遊戲，最終關卡擺著一個古老的 4 位數密碼鎖。旁邊的泛黃線索紙條上寫著一段複雜的數學謎題：此寶箱的正確解鎖密碼是一個滿足以下所有嚴格條件的 4 位數：\n① 它本身是 12、18 與 15 三個數字的公倍數\n② 將這個 4 位數的千位、百位、十位與個位數字相加的數字和，其結果必須剛好是 18 的因數\n③ 這個 4 位數在除去其百位與個位數字後，所組成的 2 位數仍然是 9 的倍數\n④ 密碼的數值範圍介於 1000 以上（含）到 2000 之間（含）\n請問小湘應該在密碼鎖上輸入哪一個唯一的正確數字，才能順利打開寶箱取得終極大獎？",
