    "source": "西松國小 114上 第一次段考 三、挑戰題 第17題",
    "batch": "段考真題",
    "category": "分數除法 / 基準量與比較量",
    "level": 4,
    "difficulty": 4,
    "question": "臺電在竹北高鐵特區建置了一套智慧微型電網，將微網內的總發電量分配給甲、乙、丙三個不同的科學園區示範基地。已知電網的分配規則與傳輸損耗如下：分配給甲基地的電力，在扣除該線路 $\\frac{1}{6}$ 的傳輸損耗後，實際送達的電力剛好等於總發電量的 $\\frac{1}{4}$；分配給乙基地的電力，除以 $\\frac{2}{3}$ 後的數值，剛好等於總發電量除以 $4\\frac{1}{6}$ 的商。其餘的電力則全額分配給丙基地（丙基地線路無損耗）。若已知丙基地最後實際收到的電力，比乙基地實際收到的電力多了 1900 瓩，請問該微型電網當時的總發電量是多少瓩？",
    "options": [
      "A. 18000",
      "B. 16200",
      "C. 6840",
      "D. 5000"
    ],
    "answerKey": "D",
    "answer": "D · 5000 瓩",
    "steps": [
      "設微型電網總發電量為 $T$ 瓩。",
      "分析甲基地分配量：扣除 $\\frac{1}{6}$ 損耗後剩下 $1 - \\frac{1}{6} = \\frac{5}{6}$。實際送達為 $\\frac{1}{4} T$，故甲分配電力 = $\\frac{1}{4} T \\div \\frac{5}{6} = \\frac{1}{4} \\times \\frac{6}{5} T = \\frac{3}{10} T$。",
      "分析乙基地分配量：乙分配量 $\\div \\frac{2}{3} = T \\div 4\\frac{1}{6}$。因 $4\\frac{1}{6} = \\frac{25}{6}$，右式 $= T \\div \\frac{25}{6} = \\frac{6}{25} T$。故乙分配電力 = $\\frac{6}{25} T \\times \\frac{2}{3} = \\frac{4}{25} T$。",
      "分析丙基地分配量：丙收到電力 = 總發電量 - 甲分配 - 乙分配 = $T - \\frac{3}{10} T - \\frac{4}{25} T$。通分分母 50：$T \\times (1 - \\frac{15}{50} - \\frac{8}{50}) = \\frac{27}{50} T$。",
      "丙比乙多 1900 瓩：$\\frac{27}{50} T - \\frac{4}{25} T = \\frac{27}{50} T - \\frac{8}{50} T = \\frac{19}{50} T = 1900$ 瓩。",
      "求解總發電量 $T = 1900 \\div \\frac{19}{50} = 1900 \\times \\frac{50}{19} = 5000$（瓩）。"
    ],
    "insight": "通分基準量：甲佔 15/50，乙佔 8/50，丙佔 27/50。丙減乙為 19/50 恰對應 1900 瓩，1/50 就是 100，總量 50 份即為 5000 瓩！",
