      "(2) 先由手電筒消耗量求待機基準速度：手電筒耗電速度為 13.5 倍，20 分鐘消耗 $10\\% - 5\\% = 5\\%$ 電量。故待機速度 $v = \\frac{5\\%}{13.5 \\times 20} = \\frac{5\\%}{270} = \\frac{1\\%}{54}$（每 54 分鐘待機消耗 1% 電量）。",
      "前 40 分鐘(手電筒+影片)消耗電量 = $22.5 \\times \\frac{1\\%}{54} \\times 40 = \\frac{50}{3}\\% = 16\\frac{2}{3}\\%$。",
