    "question": "在 921 地震園區裡，有一個周長 450 公尺的圓形公園，在圓周上每 $7\\frac{1}{2}$ 公尺設一張休息椅，每張休息椅能坐 3 人，全部的休息椅共可供幾人坐？",
    "options": [
      "A. 180 人",
      "B. 60 人",
      "C. 183 人",
      "D. 177 人"
    ],
